// @ts-check
// Some portions generated by Claude Code
//
// Round-2 server regressions, verified against a real RDF4J Server + Workbench in a real browser:
//  R2   private saved queries belong to the user signed in on the Connection page;
//  R5   Load more of a result that shrank between batches;
//  R8/9 counts are bounded per repository and use the repository size, so a slow repository does not stop the
//       counts of other repositories, and a filtered Graphs count stays correct.
const net = require('node:net');
const { test, expect } = require('@playwright/test');
const {
    createSeededRepository,
    deleteRepository,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute,
    workbenchBaseUrl
} = require('./workbench-test-helpers');

const SERVER = serverBaseUrl();
const WORKBENCH = workbenchBaseUrl();
const PAGE_DATA = 'application/vnd.rdf4j.workbench+ndjson';

function repositoryUrl(id, view) {
    return `${WORKBENCH}/repositories/${encodeURIComponent(id)}/${view}`;
}

async function putRepository(request, id, implementation) {
    const created = await request.put(`${SERVER}/repositories/${encodeURIComponent(id)}`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix config: <tag:rdf4j.org,2023:config/> .
[] a config:Repository ; config:rep.id "${id}" ; rdfs:label "Round 2 ${id}" ;
   config:rep.impl ${implementation} .`
    });
    expect([200, 201, 204], `creating ${id}`).toContain(created.status());
}

function memoryStore() {
    return '[ config:rep.type "openrdf:SailRepository" ; '
        + 'config:sail.impl [ config:sail.type "openrdf:MemoryStore" ; config:mem.persist false ] ]';
}

async function serverCount(request, id, context) {
    const query = context ? `?context=${encodeURIComponent('<' + context + '>')}` : '';
    const answer = await request.get(`${SERVER}/repositories/${encodeURIComponent(id)}/size${query}`);
    expect(answer.status()).toBe(200);
    return Number((await answer.text()).trim());
}

function digits(text) {
    return (text || '').replace(/\D/g, '');
}

/** Signs in on the Connection page like a user: server URL as shown, user and password under Advanced settings. */
async function signIn(page, user) {
    await page.goto(`${WORKBENCH}/repositories/NONE/server`, { waitUntil: 'domcontentloaded' });
    await waitForRoute(page, 'server');
    await page.locator('#server-auth-toggle').click();
    await page.locator('#server-user').fill(user);
    await page.locator('#server-password').fill(`${user}-secret`);
    // The Advanced settings pane opens over the form, so submit from the password field as a user does with Enter.
    await Promise.all([
        page.waitForURL(url => !/\/NONE\/server(?:[?#]|$)/.test(url.toString()), { timeout: 15000 }),
        page.locator('#server-password').press('Enter')
    ]);
    const cookies = await page.context().cookies(WORKBENCH);
    const credentials = cookies.find(cookie => cookie.name === 'server-user-password');
    expect(credentials, 'the Connection page stores the server credentials').toBeTruthy();
    expect(Buffer.from(credentials.value, 'base64').toString('latin1')).toBe(`${user}:${user}-secret`);
}

async function openQueryPage(page, repositoryId) {
    await page.setViewportSize({ width: 1440, height: 1000 });
    await page.goto(repositoryUrl(repositoryId, 'query'), { waitUntil: 'domcontentloaded' });
    await page.locator('#query-form').waitFor({ state: 'visible', timeout: 15000 });
    await page.locator('.CodeMirror').first().waitFor({ state: 'visible' });
}

async function setEditor(page, query) {
    await page.locator('.CodeMirror').first().evaluate((element, value) => {
        element.CodeMirror.setValue(value);
    }, query);
}

async function savedQueryRows(page, repositoryId, queryName) {
    await page.goto(repositoryUrl(repositoryId, 'saved-queries'), { waitUntil: 'domcontentloaded' });
    await waitForRoute(page, 'saved-queries');
    return page.locator('.saved-query-row').filter({ hasText: queryName });
}

test.describe('R2 private saved queries', () => {
    const repositoryId = uniqueRepositoryId('round2-private');
    const queryName = `private-${Date.now().toString(36)}`;

    test.beforeAll(async ({ request }) => {
        await createSeededRepository(request, SERVER, repositoryId);
    });

    test.afterAll(async ({ request }) => {
        await deleteRepository(request, SERVER, repositoryId);
    });

    test('a user signed in on the Connection page saves a private query that only they see', async ({ browser }) => {
        test.setTimeout(120000);
        const alice = await browser.newContext();
        const bob = await browser.newContext();
        const anonymous = await browser.newContext();
        try {
            const page = await alice.newPage();
            await signIn(page, 'alice');
            await openQueryPage(page, repositoryId);
            await setEditor(page, 'SELECT * WHERE { ?s ?p ?o } LIMIT 3');
            await page.locator('#save-query-toggle').click();
            await page.locator('#query-name').fill(queryName);
            await page.evaluate(() => window.workbench.query.handleNameChange());
            const privateBox = page.locator('#save-private');
            await expect(privateBox, 'a signed-in user may save privately').toBeEnabled();
            await privateBox.check();
            const saved = page.waitForResponse(response => response.request().method() === 'POST'
                && /\/query(?:[?#]|$)/.test(response.url())
                && new URLSearchParams(response.request().postData() || '').get('action') === 'save');
            await page.locator('#save').click();
            const saveResponse = await saved;
            expect(new URLSearchParams(saveResponse.request().postData() || '').get('save-private')).toBe('true');
            expect(saveResponse.status()).toBe(200);
            await expect(page.locator('#save-feedback')).toHaveText('Query saved.');

            const aliceRows = await savedQueryRows(page, repositoryId, queryName);
            await expect(aliceRows, 'the owner sees the private query').toHaveCount(1);
            await expect(aliceRows.locator('.saved-query-row__heading')).toContainText('alice');
            // The owner can run it: the read check uses the same signed-in user.
            await aliceRows.locator('form[data-workbench-query-execution] input[type="submit"]').click();
            await expect(aliceRows.locator('.query-results')).toHaveAttribute('aria-busy', 'false', { timeout: 30000 });
            await expect(aliceRows.locator('.query-results .query-result-status')).toContainText(/3 rows/);
            await expect(page.getByText('Current user may not read the given query.')).toHaveCount(0);

            const bobPage = await bob.newPage();
            await signIn(bobPage, 'bob');
            await expect(await savedQueryRows(bobPage, repositoryId, queryName),
                'another signed-in user does not see it').toHaveCount(0);

            const anonymousPage = await anonymous.newPage();
            await expect(await savedQueryRows(anonymousPage, repositoryId, queryName),
                'an anonymous user does not see it').toHaveCount(0);
            await openQueryPage(anonymousPage, repositoryId);
            await anonymousPage.locator('#save-query-toggle').click();
            await expect(anonymousPage.locator('#save-private'), 'an anonymous user cannot choose Private').toBeDisabled();
            const refused = await anonymousPage.request.post(repositoryUrl(repositoryId, 'query'), {
                form: { action: 'save', 'query-name': `${queryName}-anonymous`, queryLn: 'SPARQL',
                    query: 'SELECT * WHERE { ?s ?p ?o }', 'save-private': 'true', 'query-timeout': '0' }
            });
            expect(refused.status(), 'the server refuses an anonymous private save').toBe(400);
            expect((await refused.json()).error).toBe('Private saved queries require a signed-in user');
            await expect(await savedQueryRows(page, repositoryId, `${queryName}-anonymous`)).toHaveCount(0);

            // Clean up as the owner.
            const urn = (await (await savedQueryRows(page, repositoryId, queryName)).getAttribute('id')).replace(/-div$/, '');
            const deleted = await page.request.post(repositoryUrl(repositoryId, 'saved-queries'), { form: { delete: urn } });
            expect(deleted.status()).toBe(200);
        } finally {
            await alice.close();
            await bob.close();
            await anonymous.close();
        }
    });
});

test.describe('R5 Load more of a changed result', () => {
    const repositoryId = uniqueRepositoryId('round2-shrink');
    const query = 'SELECT ?s ?n WHERE { ?s <urn:r5:p> ?n } ORDER BY ?n';

    async function load(request, count) {
        const triples = Array.from({ length: count }, (_unused, index) =>
            `<urn:r5:s${index}> <urn:r5:p> "${index}"^^<http://www.w3.org/2001/XMLSchema#integer> .`).join('\n');
        const loaded = await request.post(`${SERVER}/repositories/${repositoryId}/statements`, {
            headers: { 'Content-Type': 'application/n-triples' }, data: triples
        });
        expect([200, 204]).toContain(loaded.status());
    }

    async function keepBelow(request, limit) {
        const removed = await request.post(`${SERVER}/repositories/${repositoryId}/statements`, {
            form: { update: `DELETE { ?s <urn:r5:p> ?n } WHERE { ?s <urn:r5:p> ?n FILTER(?n >= ${limit}) }` }
        });
        expect([200, 204]).toContain(removed.status());
    }

    test.beforeEach(async ({ request }) => {
        await putRepository(request, repositoryId, memoryStore());
        await load(request, 10);
    });

    test.afterEach(async ({ request }) => {
        await deleteRepository(request, SERVER, repositoryId);
    });

    test('Load more after rows were deleted ends with the rows that remain', async ({ page, request }) => {
        const errors = [];
        page.on('pageerror', error => errors.push(error.message));
        await openQueryPage(page, repositoryId);
        await page.locator('#query-form').evaluate(form => {
            const control = document.createElement('input');
            control.type = 'hidden';
            control.name = 'batch-size';
            control.value = '4';
            form.appendChild(control);
        });
        await setEditor(page, query);
        await page.locator('#exec').click();
        const results = page.locator('#query-results');
        const result = results.locator('.query-result-layout');
        await expect(results).toHaveAttribute('aria-busy', 'false', { timeout: 30000 });
        await expect(result.locator('.query-result-status')).toHaveText(/^10 rows · complete/);
        await expect(result.locator('.query-result-load-more')).toBeVisible();

        await keepBelow(request, 5);
        const continuation = page.waitForResponse(response => response.request().method() === 'POST'
            && /\/query(?:[?#]|$)/.test(response.url())
            && new URLSearchParams(response.request().postData() || '').get('batch-offset') === '4');
        await result.locator('.query-result-load-more').click();
        const sent = new URLSearchParams((await continuation).request().postData() || '');
        expect(sent.get('batch-known-total')).toBe('10');
        await expect(results).toHaveAttribute('aria-busy', 'false', { timeout: 30000 });

        await expect(result.locator('.query-result-status'), 'the result ends with the rows that remain')
            .toHaveText(/^5 rows · complete/);
        await expect(result.locator('.query-result-load-more')).toBeHidden();
        await expect(result).not.toContainText(/protocol|failed|error/i);
        await expect(result.locator('tbody tr[data-query-row-index]')).toHaveCount(5);
        expect(errors).toEqual([]);
    });

    test('the server answers a continuation of a changed result with a total that agrees with has-more',
        async ({ request }) => {
            const continuation = async (offset, knownTotal) => {
                const answer = await request.post(repositoryUrl(repositoryId, 'query'), {
                    headers: { Accept: PAGE_DATA },
                    form: { action: 'exec', ref: 'text', queryLn: 'SPARQL', query, 'batch-size': '4',
                        'batch-offset': String(offset), 'batch-known-total': String(knownTotal) }
                });
                expect(answer.status()).toBe(200);
                const records = (await answer.text()).trim().split('\n').map(line => JSON.parse(line));
                const end = records[records.length - 1];
                expect(end.type).toBe('end');
                return end.metadata;
            };
            await keepBelow(request, 6);
            for (const [offset, knownTotal, hasMore, total] of [[4, 10, false, 6], [8, 10, false, 6], [0, 3, true, 5]]) {
                const metadata = await continuation(offset, knownTotal);
                expect(metadata['result-has-more'], `offset ${offset}`).toBe(hasMore);
                expect(metadata['total-result-count'], `offset ${offset}`).toBe(total);
                expect(metadata['result-has-more'], `offset ${offset}: has-more agrees with the total`)
                    .toBe(metadata['total-result-count'] > metadata['result-next-offset']);
            }
        });
});

test.describe('R8/R9 counts of a repository while another one is slow', () => {
    const normalId = uniqueRepositoryId('round2-counts');
    const slowId = uniqueRepositoryId('round2-slow');
    const sockets = new Set();
    let blackHole;

    test.beforeAll(async ({ request }) => {
        // A SPARQL endpoint that accepts connections and never answers: a slow or unreachable repository.
        blackHole = net.createServer(socket => {
            sockets.add(socket);
            socket.on('close', () => sockets.delete(socket));
            socket.on('error', () => {});
        });
        await new Promise(resolve => blackHole.listen(0, '127.0.0.1', resolve));
        const port = blackHole.address().port;
        await putRepository(request, slowId, `[ config:rep.type "openrdf:SPARQLRepository" ; `
            + `config:sparql.queryEndpoint <http://127.0.0.1:${port}/sparql> ]`);
        await createSeededRepository(request, SERVER, normalId, { graphs: ['bsbm', 'spl'] });
        const added = await request.post(`${SERVER}/repositories/${normalId}/statements`, {
            headers: { 'Content-Type': 'application/n-triples' },
            data: '<urn:round2:default> <http://www.w3.org/2000/01/rdf-schema#label> "in the default graph" .'
        });
        expect([200, 204]).toContain(added.status());
    });

    test.afterAll(async ({ request }) => {
        for (const socket of sockets) {
            socket.destroy();
        }
        await new Promise(resolve => blackHole.close(resolve));
        await deleteRepository(request, SERVER, slowId);
        await deleteRepository(request, SERVER, normalId);
    });

    test('Summary, Graphs, Types and Clear count a repository while another repository does not answer',
        async ({ page, request }) => {
            test.setTimeout(180000);
            // Ask for the slow repository's Summary counts, again and again, more often than the Workbench lets counts
            // run at once: each count stays stuck in the repository after the page stopped waiting for it.
            const abandoned = [];
            for (let round = 0; round < 8; round++) {
                abandoned.push(...await Promise.all(Array.from({ length: 10 }, () => request.get(
                    `${repositoryUrl(slowId, 'summary')}?counts=true`, { headers: { Accept: PAGE_DATA } }))));
            }
            await page.setViewportSize({ width: 1440, height: 1000 });

            const size = await serverCount(request, normalId);
            const bsbm = await serverCount(request, normalId, 'http://example.org/graph/bsbm');
            const spl = await serverCount(request, normalId, 'http://example.org/graph/spl');

            await page.goto(repositoryUrl(normalId, 'summary'), { waitUntil: 'domcontentloaded' });
            await waitForRoute(page, 'summary');
            const statements = page.locator('#workbench-summary .workbench-kv__row').filter({ hasText: 'Statements' })
                .locator('dd');
            await expect.poll(async () => digits(await statements.textContent()), { timeout: 15000 }).toBe(String(size));
            await expect.poll(async () => digits(await page.locator('#workbench-summary .workbench-kv__row')
                .filter({ hasText: 'Named graphs' }).locator('dd').textContent())).toBe('2');

            await page.goto(repositoryUrl(normalId, 'contexts'), { waitUntil: 'domcontentloaded' });
            await waitForRoute(page, 'contexts');
            const graphCounts = page.locator('#contexts-results td.workbench-count-cell');
            await expect.poll(async () => (await graphCounts.allTextContents()).map(digits).sort(), { timeout: 15000 })
                .toEqual([String(bsbm), String(spl), '1'].sort());

            const filter = page.locator('#contexts-filter');
            await filter.fill('BSBM');
            await Promise.all([
                page.waitForURL(/[?&]filter=BSBM/, { waitUntil: 'commit' }),
                filter.press('Enter')
            ]);
            await waitForRoute(page, 'contexts');
            await expect(page.locator('#contexts-results tbody tr')).toHaveCount(1);
            await expect(page.locator('#contexts-results tbody tr')).toContainText('bsbm');
            await expect.poll(async () => (await graphCounts.allTextContents()).map(digits), { timeout: 15000 })
                .toEqual([String(bsbm)]);

            await page.goto(repositoryUrl(normalId, 'types'), { waitUntil: 'domcontentloaded' });
            await waitForRoute(page, 'types');
            const typeCounts = page.locator('#types-results td.workbench-count-cell');
            await expect.poll(async () => {
                const texts = await typeCounts.allTextContents();
                return texts.length > 0 && texts.every(value => /^\d[\d,.\s]*$/.test(value.trim()));
            }, { timeout: 15000 }).toBe(true);

            await page.goto(repositoryUrl(normalId, 'clear'), { waitUntil: 'domcontentloaded' });
            await waitForRoute(page, 'clear');
            const submit = page.locator('#clear-form button[type="submit"]');
            await expect(submit).toBeEnabled({ timeout: 15000 });
            await expect(submit).toContainText('Clear entire repository');
            await expect.poll(async () => digits((await page.locator('#context option').first().textContent())
                .split('—')[1]), { timeout: 15000 }).toBe(String(size));

            // The slow repository itself answers its pages, with counts that did not finish.
            for (const answer of abandoned) {
                expect(answer.status()).toBe(200);
                expect(await answer.text()).toContain('"counts-timed-out":true');
            }
            await page.goto(repositoryUrl(slowId, 'summary'), { waitUntil: 'domcontentloaded' });
            await waitForRoute(page, 'summary');
            await expect(page.locator('#workbench-summary .workbench-kv__row').filter({ hasText: 'Statements' })
                .locator('dd'), 'the slow repository shows no count').toHaveText('—', { timeout: 15000 });
        });
});
